// What makes images and textures for the runtime itself (movies, the GUI, textures of models) holds back the device that a program without Graphics
// gets when it makes its own (ensure_offscreen): those have to work as before, without a GPU or a window.

#pragma once

extern "C" void bb_offscreen_hold(int delta);

struct offscreen_hold {
	offscreen_hold() { bb_offscreen_hold(1); }
	~offscreen_hold() { bb_offscreen_hold(-1); }
	offscreen_hold(offscreen_hold const&)            = delete;
	offscreen_hold& operator=(offscreen_hold const&) = delete;
};
